// Enum for readable status codes
public enum OrderStatus
{
    Pending = 1,
    Processing = 2,
    Shipped = 3,
    Delivered = 4,
    Cancelled = 5
}

public class Order
{
    // Instance members
    public int Id { get; set; }
    public OrderStatus Status { get; set; }

