using System;

// Struct = Value type
public struct Point
{
    public int X;
    public int Y;
}

// Class = Reference type
public class Person
{
    public string Name;
}

public class Program
{
    static void Main()
    {
        // Value type behavior
        Point p1 = new Point { X = 10, Y = 20 };
        Point p2 = p1; // Creates a COPY
        p2.X = 99;
        Console.WriteLine($"p1.X = {p1.X}, p2.X = {p2.X}"); // p1 still 10

        // Reference type behavior
        Person person1 = new Person { Name = "Alice" };
        Person person2 = person1; // Copies the REFERENCE
        person2.Name = "Bob";
        Console.WriteLine($"person1.Name = {person1.Name}"); // Bob! Same object.

        // Passing to methods
        int number = 5;
        ModifyValue(number);
        Console.WriteLine($"number after method: {number}"); // Still 5

        Person refPerson = new Person { Name = "Charlie" };
        ModifyReference(refPerson);
        Console.WriteLine($"refPerson.Name after method: {refPerson.Name}"); // Changed!
    }

    static void ModifyValue(int x) { x = 100; }
    static void ModifyReference(Person p) { p.Name = "Modified"; }
}

