using System;

public class UserProfile
{
    public string Name { get; set; } = string.Empty;
    public string? Bio { get; set; }        // Nullable reference type
    public int? Age { get; set; }           // Nullable value type
    public DateTime? LastLogin { get; set; }
}

public class Program
{
    static void Main()
    {
        UserProfile? user = GetUser();

        // Null-conditional operator ?.
        int nameLength = user?.Name?.Length ?? 0;
        Console.WriteLine($"Name length: {nameLength}");

        // Null-coalescing ??
        string displayName = user?.Name ?? "Anonymous";
        Console.WriteLine($"Display: {displayName}");

        // Null-coalescing assignment ??=
        user ??= new UserProfile { Name = "Default User" };

        // HasValue and Value for nullable value types
        int? score = null;
        if (score.HasValue)
        {
            Console.WriteLine($"Score: {score.Value}");
        }
        else
        {
            Console.WriteLine("No score available.");
        }

        int safeScore = score ?? 0; // Default to 0 if null
        Console.WriteLine($"Safe score: {safeScore}");
    }

    static UserProfile? GetUser()
    {
        return null; // Simulating missing user
    }
}

