using System;
using System.Collections.Generic;
using System.Linq;

public class Student
{
    public string Name { get; set; }
    public int Grade { get; set; }
    public double Gpa { get; set; }
}

public class Program
{
    static void Main()
    {
        var students = new List<Student>
        {
            new() { Name = "Alice", Grade = 10, Gpa = 3.8 },
            new() { Name = "Bob", Grade = 11, Gpa = 3.2 },
            new() { Name = "Charlie", Grade = 10, Gpa = 3.9 },
            new() { Name = "Diana", Grade = 12, Gpa = 3.5 }
        };

        // Method syntax with lambdas
        var honorRoll = students
            .Where(s => s.Gpa >= 3.5)
            .OrderByDescending(s => s.Gpa)
            .Select(s => new { s.Name, s.Gpa })
            .ToList();

        Console.WriteLine("Honor Roll:");
        honorRoll.ForEach(s => Console.WriteLine($"  {s.Name}: {s.Gpa}"));

        // Query syntax
        var sophomores = from s in students
                         where s.Grade == 10
                         orderby s.Name
                         select s.Name;

        Console.WriteLine($"Sophomores: {string.Join(", ", sophomores)}");

        // Aggregation
        double avgGpa = students.Average(s => s.Gpa);
        bool allPassing = students.All(s => s.Gpa >= 2.0);
        var topStudent = students.FirstOrDefault(s => s.Gpa > 3.8);

        Console.WriteLine($"Average GPA: {avgGpa:F2}");
        Console.WriteLine($"All passing: {allPassing}");
        Console.WriteLine($"Top student: {topStudent?.Name ?? "None"}");
    }
}

