using System;
using System.Collections.Generic;
using System.Linq;

public class CollectionsDemo
{
    static void Main()
    {
        // HashSet: Unique items, fast lookup
        var tags = new HashSet<string> { "csharp", "dotnet", "web" };
        tags.Add("csharp"); // Duplicate ignored
        tags.Add("sql");
        Console.WriteLine($"Tags: {string.Join(", ", tags)}");
        Console.WriteLine($"Has 'web': {tags.Contains("web")}");

        // Queue: FIFO
        var printQueue = new Queue<string>();
        printQueue.Enqueue("Document1.pdf");
        printQueue.Enqueue("Photo.jpg");
        printQueue.Enqueue("Report.docx");
        Console.WriteLine($"\nPrinting: {printQueue.Dequeue()}"); // Document1.pdf
        Console.WriteLine($"Next in line: {printQueue.Peek()}");  // Photo.jpg

        // Stack: LIFO
        var history = new Stack<string>();
        history.Push("Homepage");
        history.Push("Products");
        history.Push("Cart");
        Console.WriteLine($"\nCurrent: {history.Peek()}"); // Cart
        Console.WriteLine($"Going back to: {history.Pop()}"); // Cart removed
        Console.WriteLine($"Now at: {history.Peek()}"); // Products

        // SortedList
        var scores = new SortedList<string, int>();
        scores.Add("Bob", 85);
