using System.Threading.Tasks;

public class AsyncDemo
{
    static async Task Main(string[] args)
    {
        Console.WriteLine("Starting download simulation...");

        // Simulate a slow operation without blocking
        await SimulateDownloadAsync("file1.zip");
        await SimulateDownloadAsync("file2.zip");

        // Running tasks in parallel
        var task1 = SimulateDownloadAsync("image1.png");
        var task2 = SimulateDownloadAsync("image2.png");
        await Task.WhenAll(task1, task2);

        // Async file read
        string content = await File.ReadAllTextAsync("notes.txt");
        Console.WriteLine($"File read: {content.Length} characters");

        Console.WriteLine("All operations complete.");
    }

    static async Task SimulateDownloadAsync(string filename)
    {
        Console.WriteLine($"Starting {filename}...");
        await Task.Delay(1000); // Simulate 1 second delay (non-blocking)
        Console.WriteLine($"Finished {filename}.");
    }
}

