using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;

public class TaskItem
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public bool IsCompleted { get; set; }
    public DateTime CreatedAt { get; set; } = DateTime.Now;
}

public class TaskManager
{
    private List<TaskItem> _tasks = new();
    private int _nextId = 1;
    private const string FileName = "tasks.json";

    public TaskManager()
    {
        LoadTasks();
    }

    public void AddTask(string title)
    {
        _tasks.Add(new TaskItem { Id = _nextId++, Title = title });
        Console.WriteLine($"Task added: {title}");
        SaveTasks();
    }

    public void ListTasks()
    {
        if (!_tasks.Any())
        {
            Console.WriteLine("No tasks found.");
            return;
        }

        foreach (var task in _tasks.OrderBy(t => t.IsCompleted).ThenBy(t => t.Id))
        {
            string status = task.IsCompleted ? "[X]" : "[ ]";
            Console.WriteLine($"{status} {task.Id}. {task.Title} ({task.CreatedAt:g})");
        }
    }

    public void CompleteTask(int id)
    {
        var task = _tasks.FirstOrDefault(t => t.Id == id);
        if (task == null)
        {
            Console.WriteLine("Task not found.");
            return;
        }
        task.IsCompleted = true;
        Console.WriteLine($"Completed: {task.Title}");
        SaveTasks();
    }

    private void SaveTasks()
    {
        var json = JsonSerializer.Serialize(_tasks, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(FileName, json);
    }

    private void LoadTasks()
    {
        if (!File.Exists(FileName)) return;
        try
        {
            var json = File.ReadAllText(FileName);
            _tasks = JsonSerializer.Deserialize<List<TaskItem>>(json) ?? new();
            _nextId = _tasks.Count > 0 ? _tasks.Max(t => t.Id) + 1 : 1;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to load tasks: {ex.Message}");
        }
    }
}

public class Program
{
    static void Main()
    {
        var manager = new TaskManager();
        while (true)
        {
            Console.WriteLine("\n1. Add Task | 2. List Tasks | 3. Complete Task | 4. Exit");
            Console.Write("Choice: ");
            var choice = Console.ReadLine();

            switch (choice)
            {
                case "1":
                    Console.Write("Enter task title: ");
                    manager.AddTask(Console.ReadLine()!);
                    break;
                case "2":
                    manager.ListTasks();
                    break;
                case "3":
                    Console.Write("Enter task ID: ");
                    if (int.TryParse(Console.ReadLine(), out int id))
                        manager.CompleteTask(id);
                    break;
                case "4":
                    return;
            }
        }
    }
}
